const UNITS: Record<string, number> = { s: 1, m: 60, h: 3600, d: 86400 };

export function parseDuration(text: string): number {
  const pattern = /^\s*(?:\d+[dhms]\s*)+$/;
  if (!pattern.test(text)) throw new Error(`invalid duration: ${text}`);
  let total = 0;
  for (const [count, unit] of text.matchAll(/(\d+)([dhms])/g)) {
    total += Number(count) * UNITS[unit];
  }
  return total;
}
